-- SafePlum 운영팀 글 2차 (2026-10-19) — 게시판 활성화용: 홍보·정보 공유·소통 글 10개
-- 운영자(admin) 계정으로 올린다. 가짜 회원·가짜 닉네임은 만들지 않는다.
-- 사용법: SQL Editor 에 통째로 붙여 넣고 Run. 다시 실행하면 같은 제목의 글은 건너뛴다.
do $$
declare
  uid uuid := (select id from auth.users where email = 'tjsrlfhzpt@gmail.com');
  r record;
  n int := 0;
begin
  if uid is null then raise exception '이 이메일로 가입한 계정이 없습니다. 이메일을 확인하세요.'; end if;
  if not exists (select 1 from public.profiles where id = uid and role = 'admin') then raise exception '이 계정은 운영자(admin)가 아닙니다.'; end if;
  perform set_config('request.jwt.claim.sub', uid::text, true);
  perform set_config('request.jwt.claims', json_build_object('sub', uid::text, 'role', 'authenticated')::text, true);
  for r in
    select * from (values
      ('free', '정보 공유', '[운영팀] 안전·보건관리자 실무·취업 오픈채팅방을 운영하고 있어요',
       E'안녕하세요, SafePlum 운영팀입니다.\n\n안전관리자·보건관리자분들이 실무 고민과 채용 정보를 편하게 나누는 카카오톡 오픈채팅방을 운영하고 있습니다.\n\n· 안전·보건 직무 채용 정보 공유\n· 법령 개정, 서류 작성, 점검 준비 같은 실무 질문\n· 이직·자격증·교육 이야기\n\n참여 주소: https://open.kakao.com/o/glnqB5Qi\n\n오픈채팅방에서도 회사명·실명·연락처 같은 개인정보는 올리지 말아 주세요. 게시판에 남겨 주시는 글은 검색으로 다시 찾아볼 수 있어서, 오래 두고 볼 정보는 이 게시판에 정리해 주시면 더 좋습니다.'),
      ('free', '정보 공유', '[운영팀] 네이버 블로그에서 법령 개정·실무 정보를 정리하고 있습니다',
       E'SafePlum 네이버 블로그를 열었습니다.\nhttps://blog.naver.com/safeplum\n\n블로그에서는 이런 글을 올리고 있어요.\n\n· 입법예고·법령 개정안을 조문별로 풀어 정리\n· 합동점검, 위험성평가, TBM처럼 자주 하는 업무의 절차와 작성 방법\n· 짧은 영상(안전보건 1분 상식)과 함께 보는 실무 정리\n\n다뤄 줬으면 하는 주제가 있으면 이 글에 댓글로 남겨 주세요. 요청이 많은 주제부터 정리하겠습니다.'),
      ('free', '정보 공유', '[운영팀] 새 기능: 법령 AI 질문 — 조문을 찾아 근거와 함께 답합니다',
       E'법령 AI 질문 기능을 열었습니다.\nhttps://safeplum.com/tools/law-ai/\n\n질문을 적으면\n① 산안법·시행령·시행규칙·안전보건규칙·중처법 현행 조문에서 관련 조문을 먼저 찾고\n② 그 조문만 근거로 AI가 답을 정리합니다.\n답마다 근거 조문과 원문 링크가 붙습니다.\n\n쓰기 전에 알아 두실 점\n· 본인의 Google Gemini API 키로 동작합니다(키 발급은 화면 안내 참고). 키는 이 브라우저에만 저장되고 SafePlum 서버로 보내지 않습니다.\n· 별표(교육시간 표 등)·고시·행정해석·판례는 아직 검색 대상이 아닙니다. 이런 질문은 "제공된 조문에서는 확인되지 않습니다"라고 답할 수 있어요.\n· AI 답변은 참고용이며 법적 효력이 없습니다. 실제 판단은 원문과 고용노동부(국번 없이 1350) 상담으로 확인해 주세요.\n\n써 보시고 이상한 답이 나오면 질문과 함께 댓글로 알려 주세요.'),
      ('free', '정보 공유', '[운영팀] 새 기능: 보호구·방호장치 인증 확인 기록',
       E'안전모·안전화·보안경, 자동전격방지기·연삭기 덮개 같은 보호구·방호장치를 사거나 지급하기 전에 확인하는 도구를 만들었습니다.\nhttps://safeplum.com/tools/gear-cert/\n\n· 품목을 고르면 안전인증 대상인지 자율안전확인 대상인지 보여 줍니다(산안법 시행령 제74조·제77조).\n· 안전보건공단 안전인증·자율안전확인 현황과 발급문서 진위확인으로 바로 연결됩니다.\n· 확인한 결과를 기록해 A4로 인쇄하거나 엑셀(CSV)로 저장할 수 있습니다.\n\n인증·신고가 없는 대상품은 누구도 사용할 수 없습니다(법 제87조·제92조). 납품 받을 때 한 번씩 확인해 두시면 좋습니다.'),
      ('free', '정보 공유', '[운영팀] 안전작업수칙 게시물, 설비 앞에 붙일 것 바로 만들어 쓰세요',
       E'작업장·설비 앞에 붙이는 안전작업수칙 게시물 만들기를 열었습니다.\nhttps://safeplum.com/tools/rule-sign/\n\n· 안전보건공단 「표준작업 안전수칙(제조분야)」 101개 수칙에서 골라 쓰거나 직접 작성\n· 안전보건표지 그림 최대 4개, 회사명·로고 넣기\n· A4·A3, 가로·세로 인쇄\n\n수칙은 TBM이나 안전보건교육 때 함께 읽고, 위험성평가 결과가 바뀌면 고쳐 다시 붙이는 걸 권합니다. 우리 현장에서 실제로 쓰는 수칙 예시가 있다면 댓글로 공유해 주세요. 다른 분들께 큰 도움이 됩니다.'),
      ('free', '정보 공유', '[정리] 안전보건 업무, 매일부터 연간까지 주기별로 정리했습니다',
       E'캘린더에 무엇을 등록해야 할지 자주 물어보셔서 주기별로 정리했습니다. 모든 사업장에 똑같이 적용되는 일정표는 아니고, 법정 주기는 업종·규모·도급 여부에 따라 달라집니다.\n\n매일\n· TBM으로 당일 작업 위험요인 공유\n· 작업허가, LOTO 등 해당 작업의 안전조치 확인\n· 작업·설비 변경, 비정상 상태 확인\n\n매주(실무 운영 예시)\n· 정해진 구역·설비·통로 순회점검\n· 지난 지적사항이 실제로 개선됐는지 재확인\n\n매월\n· 도급 사업장: 안전보건 협의체 회의 매월 1회 이상, 결과 기록·보존(시행규칙 제79조)\n\n분기\n· 산업안전보건위원회 정기회의(대상 사업장, 시행령 제37조)\n· 도급 합동 안전보건점검: 건설업·선박 및 보트 건조업 2개월에 1회 이상, 그 밖의 사업 분기 1회 이상(시행규칙 제82조)\n\n반기\n· 중처법 적용 사업장: 안전보건 관계 법령 의무이행 점검 반기 1회 이상(중처법 시행령 제5조)\n\n연간\n· 위험성평가 결과 적정성 재검토, 사고·아차사고·점검 결과를 반영해 내년 계획 수립\n\n주기보다 중요한 건 실행과 증빙입니다. 누가, 언제까지, 어디에 기록할지 정해 두세요.\n법정 일정 계산: https://safeplum.com/tools/schedule/'),
      ('free', '정보 공유', '[정리] 아차사고, 다치지 않았어도 위험성평가 대상입니다',
       E'"다칠 뻔했지만 안 다쳤으니 됐다"로 넘기기 쉬운 게 아차사고입니다.\n\n「사업장 위험성평가에 관한 지침」 제5조의2제2항은 사업주가 사업장 내 부상 또는 질병으로 이어질 가능성이 있었던 상황(아차사고)을 확인한 경우, 그 사고를 일으킨 유해·위험요인을 위험성평가 대상에 포함하도록 정하고 있습니다.\n\n현장에서 이렇게 해 보세요.\n① 발견 즉시 조치 — 표지 설치, 출입 통제 등으로 2차 피해 방지\n② 바로 알리기 — 동료·관리감독자에게 공유\n③ 원인 제거 — 물기만 닦지 말고 새는 곳까지\n④ 기록·공유 — 아차사고 기록을 남기고 위험성평가·TBM에서 공유\n\n아차사고를 많이 보고하는 현장이 위험한 현장이 아니라, 잘 관리되는 현장입니다. 여러분 현장에서는 아차사고 보고를 어떻게 독려하고 계신지 댓글로 나눠 주세요.'),
      ('free', '정보 공유', '[정리] 밀폐공간 적정공기 기준과 긴급구조훈련 주기',
       E'밀폐공간 작업 전 꼭 확인할 숫자를 정리했습니다(산업안전보건기준에 관한 규칙).\n\n적정공기(제618조)\n· 산소 18% 이상 23.5% 미만\n· 이산화탄소 1.5% 미만\n· 일산화탄소 30ppm 미만\n· 황화수소 10ppm 미만\n\n작업 전 확인(제619조·제619조의2)\n· 작업 시작 전(중단 후 다시 시작할 때 포함) 산소·유해가스 농도 측정\n· 작업 정보, 작업자·감시인, 측정 결과, 보호구, 비상연락체계를 확인하고 출입구에 게시\n\n긴급 구조훈련(제640조)\n· 밀폐공간 작업 근로자 대상 6개월에 1회 이상\n· 비상연락체계 운영, 구조용 장비 사용, 공기호흡기·송기마스크 착용, 응급처치\n· 결과 기록·보존\n\n구조하러 들어간 사람까지 쓰러지는 사고가 반복됩니다. 보호구 없이 절대 들어가지 마세요.\n밀폐공간 가스농도 기록: https://safeplum.com/tools/confined/'),
      ('free', '현장 이야기', '[소통] 우리 현장의 "이건 꼭 지킨다" 안전수칙 하나씩 남겨 주세요',
       E'현장마다 사고를 겪고 나서 생긴, 혹은 오래 지켜 온 수칙이 하나씩은 있습니다.\n\n예)\n· 지게차 후진할 때는 무조건 유도자 배치\n· 컨베이어 청소는 LOTO 걸고 열쇠는 본인이 보관\n· 냉동창고는 들어가기 전에 출입 명부부터\n\n여러분 현장의 수칙을 댓글로 하나씩 남겨 주세요. 업종만 적어 주시면 되고, 회사 이름은 적지 말아 주세요. 모인 수칙은 정리해서 안전작업수칙 게시물 예시로도 소개하겠습니다.'),
      ('free', '자료 요청', '[소통] 요즘 가장 손이 많이 가는 안전보건 서류는 무엇인가요?',
       E'다음에 만들 작성기를 정하려고 합니다.\n\n지금 SafePlum에는 위험성평가서, TBM 일지, 작업허가서, 합동점검, 순회점검, 안전보건교육 일지, 협의체·위원회 회의록 등이 있습니다.\nhttps://safeplum.com/tools/\n\n· 가장 시간이 오래 걸리는 서류\n· 양식이 없어 매번 새로 만드는 서류\n· 작성기는 있는데 이런 기능이 있었으면 하는 점\n\n댓글로 알려 주세요. 많이 나온 것부터 검토하겠습니다(반영 여부와 시기는 약속드리기 어렵지만, 댓글은 모두 읽습니다).')
    ) as t(board, category, title, body)
  loop
    if not exists (select 1 from public.posts where author_id = uid and title = r.title and deleted_at is null) then
      insert into public.posts (board, category, title, body, author_id, notice) values (r.board, r.category, r.title, r.body, uid, false);
      n := n + 1;
    end if;
  end loop;
  raise notice '새로 올린 글: %개', n;
end $$;
